package com.parion.aidat;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import java.text.*;import java.util.*;
public class DbHelper extends SQLiteOpenHelper{
 static final int VERSION=3;final SimpleDateFormat iso=new SimpleDateFormat("yyyy-MM-dd",Locale.US);
 public DbHelper(Context c){super(c,"parion_aidat.db",null,VERSION);iso.setLenient(false);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE athletes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,birthYear INTEGER DEFAULT 0,birthDate TEXT,tckn TEXT,startDate TEXT,athletePhone TEXT,parent TEXT,phone TEXT,motherName TEXT,motherPhone TEXT,fatherName TEXT,fatherPhone TEXT,school TEXT,classBranch TEXT,groupName TEXT,monthlyFee REAL NOT NULL DEFAULT 0,scholarship INTEGER NOT NULL DEFAULT 0,illnesses TEXT,notes TEXT,leaveDate TEXT,leaveReason TEXT,photoUri TEXT,tshirtQty INTEGER DEFAULT 0,jerseyQty INTEGER DEFAULT 0,tracksuitQty INTEGER DEFAULT 0,active INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,year INTEGER NOT NULL,month INTEGER NOT NULL,amount REAL NOT NULL,paymentDate TEXT,method TEXT,note TEXT,UNIQUE(athleteId,year,month))");d.execSQL("CREATE TABLE fee_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,effectiveDate TEXT NOT NULL,fee REAL NOT NULL,scholarship INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,isSportsSchool INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE group_schedule(id INTEGER PRIMARY KEY AUTOINCREMENT,groupName TEXT NOT NULL,weekday INTEGER NOT NULL,effectiveFrom TEXT NOT NULL,effectiveTo TEXT)");d.execSQL("CREATE TABLE group_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,effectiveFrom TEXT NOT NULL,effectiveTo TEXT)");d.execSQL("CREATE TABLE attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,trainingDate TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 0,UNIQUE(athleteId,trainingDate))");d.execSQL("CREATE TABLE inventory(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,stock INTEGER NOT NULL DEFAULT 0,buyPrice REAL NOT NULL DEFAULT 0,sellPrice REAL NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE inventory_tx(id INTEGER PRIMARY KEY AUTOINCREMENT,itemId INTEGER NOT NULL,txDate TEXT NOT NULL,qty INTEGER NOT NULL,type TEXT NOT NULL,buyUnit REAL NOT NULL DEFAULT 0,sellUnit REAL NOT NULL DEFAULT 0,athleteId INTEGER)");seed(d);}
 public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){String[] a={"ALTER TABLE athletes ADD COLUMN birthDate TEXT","ALTER TABLE athletes ADD COLUMN tckn TEXT","ALTER TABLE athletes ADD COLUMN startDate TEXT","ALTER TABLE athletes ADD COLUMN athletePhone TEXT","ALTER TABLE athletes ADD COLUMN motherName TEXT","ALTER TABLE athletes ADD COLUMN motherPhone TEXT","ALTER TABLE athletes ADD COLUMN fatherName TEXT","ALTER TABLE athletes ADD COLUMN fatherPhone TEXT","ALTER TABLE athletes ADD COLUMN school TEXT","ALTER TABLE athletes ADD COLUMN classBranch TEXT","ALTER TABLE athletes ADD COLUMN scholarship INTEGER NOT NULL DEFAULT 0","ALTER TABLE athletes ADD COLUMN illnesses TEXT","ALTER TABLE athletes ADD COLUMN notes TEXT","ALTER TABLE athletes ADD COLUMN leaveDate TEXT","ALTER TABLE athletes ADD COLUMN leaveReason TEXT","ALTER TABLE athletes ADD COLUMN photoUri TEXT","ALTER TABLE athletes ADD COLUMN tshirtQty INTEGER DEFAULT 0","ALTER TABLE athletes ADD COLUMN jerseyQty INTEGER DEFAULT 0","ALTER TABLE athletes ADD COLUMN tracksuitQty INTEGER DEFAULT 0"};for(String s:a)try{d.execSQL(s);}catch(Exception e){}d.execSQL("CREATE TABLE IF NOT EXISTS fee_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,effectiveDate TEXT NOT NULL,fee REAL NOT NULL,scholarship INTEGER NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,isSportsSchool INTEGER NOT NULL DEFAULT 1)");d.execSQL("CREATE TABLE IF NOT EXISTS group_schedule(id INTEGER PRIMARY KEY AUTOINCREMENT,groupName TEXT NOT NULL,weekday INTEGER NOT NULL,effectiveFrom TEXT NOT NULL)");d.execSQL("CREATE TABLE IF NOT EXISTS attendance(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,trainingDate TEXT NOT NULL,present INTEGER NOT NULL DEFAULT 0,UNIQUE(athleteId,trainingDate))");d.execSQL("CREATE TABLE IF NOT EXISTS inventory(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,stock INTEGER NOT NULL DEFAULT 0,buyPrice REAL NOT NULL DEFAULT 0,sellPrice REAL NOT NULL DEFAULT 0)");d.execSQL("CREATE TABLE IF NOT EXISTS inventory_tx(id INTEGER PRIMARY KEY AUTOINCREMENT,itemId INTEGER NOT NULL,txDate TEXT NOT NULL,qty INTEGER NOT NULL,type TEXT NOT NULL,buyUnit REAL NOT NULL DEFAULT 0,sellUnit REAL NOT NULL DEFAULT 0,athleteId INTEGER)");seed(d);}if(o<3){try{d.execSQL("ALTER TABLE group_schedule ADD COLUMN effectiveTo TEXT");}catch(Exception e){}d.execSQL("CREATE TABLE IF NOT EXISTS group_history(id INTEGER PRIMARY KEY AUTOINCREMENT,athleteId INTEGER NOT NULL,groupName TEXT NOT NULL,effectiveFrom TEXT NOT NULL,effectiveTo TEXT)");Cursor c=d.rawQuery("SELECT id,groupName,startDate FROM athletes",null);while(c.moveToNext()){long id=c.getLong(0);String g=c.getString(1),s=c.getString(2);if(g!=null&&!g.isEmpty()){ContentValues v=new ContentValues();v.put("athleteId",id);v.put("groupName",g);v.put("effectiveFrom",s==null||s.isEmpty()?"1900-01-01":s);d.insert("group_history",null,v);}}c.close();}}
 void seed(SQLiteDatabase d){for(String g:new String[]{"SPOR OKULU 1","SPOR OKULU 2","SPOR OKULU 3","SPOR OKULU 4"})d.execSQL("INSERT OR IGNORE INTO groups(name,isSportsSchool) VALUES(?,1)",new Object[]{g});for(String i:new String[]{"TİŞÖRT","FORMA","EŞOFMAN"})d.execSQL("INSERT OR IGNORE INTO inventory(name,stock,buyPrice,sellPrice) VALUES(?,0,0,0)",new Object[]{i});}
 public long addAthlete(String name,String bd,String tc,String sd,String ap,String mn,String mp,String fn,String fp,String school,String cb,String group,double fee,boolean burs,String ill,String notes,String ld,String lr,String photo,int tq,int jq,int eq){ContentValues v=athleteValues(name,bd,tc,sd,ap,mn,mp,fn,fp,school,cb,group,fee,burs,ill,notes,ld,lr,photo,tq,jq,eq);long id=getWritableDatabase().insert("athletes",null,v);if(id>0){updateFee(id,fee,burs,sd==null||sd.isEmpty()?"1900-01-01":sd);ContentValues h=new ContentValues();h.put("athleteId",id);h.put("groupName",group);h.put("effectiveFrom",sd==null||sd.isEmpty()?"1900-01-01":sd);getWritableDatabase().insert("group_history",null,h);}return id;}
 ContentValues athleteValues(String name,String bd,String tc,String sd,String ap,String mn,String mp,String fn,String fp,String school,String cb,String group,double fee,boolean burs,String ill,String notes,String ld,String lr,String photo,int tq,int jq,int eq){ContentValues v=new ContentValues();v.put("name",name);v.put("birthDate",bd);v.put("tckn",tc);v.put("startDate",sd);v.put("athletePhone",ap);v.put("motherName",mn);v.put("motherPhone",mp);v.put("fatherName",fn);v.put("fatherPhone",fp);v.put("school",school);v.put("classBranch",cb);v.put("groupName",group);v.put("monthlyFee",burs?0:Math.round(fee));v.put("scholarship",burs?1:0);v.put("illnesses",ill);v.put("notes",notes);v.put("leaveDate",ld);v.put("leaveReason",lr);v.put("photoUri",photo);v.put("tshirtQty",tq);v.put("jerseyQty",jq);v.put("tracksuitQty",eq);v.put("active",ld==null||ld.isEmpty()?1:0);return v;}
 public void updateAthlete(long id,String name,String bd,String tc,String sd,String ap,String mn,String mp,String fn,String fp,String school,String cb,String group,double fee,boolean burs,String ill,String notes,String ld,String lr,String photo,int tq,int jq,int eq,String changeDate){Cursor old=athlete(id);String oldGroup="";double oldFee=0;int oldBurs=0;if(old.moveToFirst()){oldGroup=s(old,"groupName");oldFee=old.getDouble(old.getColumnIndexOrThrow("monthlyFee"));oldBurs=old.getInt(old.getColumnIndexOrThrow("scholarship"));}old.close();getWritableDatabase().update("athletes",athleteValues(name,bd,tc,sd,ap,mn,mp,fn,fp,school,cb,group,fee,burs,ill,notes,ld,lr,photo,tq,jq,eq),"id=?",new String[]{""+id});if(!oldGroup.equals(group))changeGroup(id,newGroup(group),changeDate);if(Math.abs(oldFee-(burs?0:fee))>.01||oldBurs!=(burs?1:0))updateFee(id,fee,burs,changeDate);}
 String newGroup(String g){return g==null?"":g;}public void changeGroup(long id,String newG,String date){SQLiteDatabase d=getWritableDatabase();String prev=dayBefore(date);d.execSQL("UPDATE group_history SET effectiveTo=? WHERE athleteId=? AND effectiveTo IS NULL",new Object[]{prev,id});ContentValues h=new ContentValues();h.put("athleteId",id);h.put("groupName",newG);h.put("effectiveFrom",date);d.insert("group_history",null,h);ContentValues v=new ContentValues();v.put("groupName",newG);d.update("athletes",v,"id=?",new String[]{""+id});}
 public Cursor athletes(){return getReadableDatabase().rawQuery("SELECT * FROM athletes ORDER BY active DESC,name COLLATE NOCASE",null);}public Cursor activeAthletes(){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE active=1 ORDER BY name COLLATE NOCASE",null);}public Cursor searchAthletes(String q){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE name LIKE ? OR tckn LIKE ? ORDER BY active DESC,name COLLATE NOCASE",new String[]{q+"%",q+"%"});}public Cursor athlete(long id){return getReadableDatabase().rawQuery("SELECT * FROM athletes WHERE id=?",new String[]{""+id});}
 public Cursor athletesForGroupMonth(String g,int y,int m){String from=String.format(Locale.US,"%04d-%02d-01",y,m),to=monthEnd(y,m);return getReadableDatabase().rawQuery("SELECT DISTINCT a.* FROM athletes a JOIN group_history gh ON gh.athleteId=a.id WHERE gh.groupName=? AND gh.effectiveFrom<=? AND (gh.effectiveTo IS NULL OR gh.effectiveTo>=?) ORDER BY CASE WHEN a.birthDate IS NULL OR a.birthDate='' THEN 9999 ELSE CAST(substr(a.birthDate,1,4) AS INTEGER) END ASC,a.name COLLATE NOCASE ASC",new String[]{g,to,from});}
 public boolean memberOnDate(long id,String g,String date){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM group_history WHERE athleteId=? AND groupName=? AND effectiveFrom<=? AND (effectiveTo IS NULL OR effectiveTo>=?) LIMIT 1",new String[]{""+id,g,date,date});boolean b=c.moveToFirst();c.close();return b;}
 public Cursor groups(boolean only){return getReadableDatabase().rawQuery("SELECT * FROM groups"+(only?" WHERE isSportsSchool=1":"")+" ORDER BY name",null);}public void addGroup(String n,boolean sports){ContentValues v=new ContentValues();v.put("name",n);v.put("isSportsSchool",sports?1:0);getWritableDatabase().insertWithOnConflict("groups",null,v,SQLiteDatabase.CONFLICT_IGNORE);}public boolean deleteGroup(String n){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM athletes WHERE groupName=? AND active=1",new String[]{n});c.moveToFirst();int x=c.getInt(0);c.close();if(x>0)return false;return getWritableDatabase().delete("groups","name=?",new String[]{n})>0;}
 public boolean isPaid(long id,int y,int m){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM payments WHERE athleteId=? AND year=? AND month=?",new String[]{""+id,""+y,""+m});boolean b=c.moveToFirst();c.close();return b;}public void markPaid(long id,int y,int m,double amount,String method){ContentValues v=new ContentValues();v.put("athleteId",id);v.put("year",y);v.put("month",m);v.put("amount",Math.round(amount));v.put("paymentDate",iso.format(new Date()));v.put("method",method);getWritableDatabase().insertWithOnConflict("payments",null,v,SQLiteDatabase.CONFLICT_REPLACE);}public double collected(int y,int m){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(amount),0) FROM payments WHERE year=? AND month=?",new String[]{""+y,""+m});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}public Cursor paymentsFor(long id){return getReadableDatabase().rawQuery("SELECT * FROM payments WHERE athleteId=? ORDER BY year DESC,month DESC",new String[]{""+id});}
 Date parse(String s){try{return iso.parse(s);}catch(Exception e){return null;}}String s(Cursor c,String n){int i=c.getColumnIndex(n);return i<0||c.isNull(i)?"":c.getString(i);}Calendar ms(Calendar c){Calendar x=(Calendar)c.clone();x.set(Calendar.DAY_OF_MONTH,1);return x;}public String dueDate(long id,int y,int m){Cursor c=athlete(id);if(!c.moveToFirst()){c.close();return null;}Date d=parse(s(c,"startDate"));c.close();if(d==null)return String.format(Locale.US,"%04d-%02d-01",y,m);Calendar first=Calendar.getInstance();first.setTime(d);first.add(Calendar.MONTH,1);Calendar t=Calendar.getInstance();t.clear();t.set(y,m-1,1);if(t.before(ms(first)))return null;t.set(Calendar.DAY_OF_MONTH,Math.min(first.get(Calendar.DAY_OF_MONTH),t.getActualMaximum(Calendar.DAY_OF_MONTH)));return iso.format(t.getTime());}public double feeForDate(long id,String date){Cursor c=getReadableDatabase().rawQuery("SELECT fee,scholarship FROM fee_history WHERE athleteId=? AND effectiveDate<=? ORDER BY effectiveDate DESC,id DESC LIMIT 1",new String[]{""+id,date});if(c.moveToFirst()){double x=c.getInt(1)==1?0:c.getDouble(0);c.close();return x;}c.close();Cursor a=athlete(id);double x=0;if(a.moveToFirst())x=a.getInt(a.getColumnIndexOrThrow("scholarship"))==1?0:a.getDouble(a.getColumnIndexOrThrow("monthlyFee"));a.close();return x;}public double expectedForMonth(long id,int y,int m){String d=dueDate(id,y,m);return d==null?0:feeForDate(id,d);}public double expectedTotal(int y,int m){double x=0;Cursor c=activeAthletes();while(c.moveToNext())x+=expectedForMonth(c.getLong(c.getColumnIndexOrThrow("id")),y,m);c.close();return x;}public int unpaidCount(int y,int m){int n=0;Cursor c=activeAthletes();while(c.moveToNext()){long id=c.getLong(c.getColumnIndexOrThrow("id"));if(expectedForMonth(id,y,m)>0&&!isPaid(id,y,m))n++;}c.close();return n;}
 public void updateFee(long id,double fee,boolean burs,String date){ContentValues h=new ContentValues();h.put("athleteId",id);h.put("effectiveDate",date);h.put("fee",burs?0:Math.round(fee));h.put("scholarship",burs?1:0);getWritableDatabase().insert("fee_history",null,h);ContentValues v=new ContentValues();v.put("monthlyFee",burs?0:Math.round(fee));v.put("scholarship",burs?1:0);getWritableDatabase().update("athletes",v,"id=?",new String[]{""+id});}public int bulkUpdateFee(String g,double oldFee,double newFee,String date){Cursor c=getReadableDatabase().rawQuery("SELECT id FROM athletes WHERE active=1 AND groupName=? AND ABS(monthlyFee-?)<.01 AND scholarship=0",new String[]{g,""+oldFee});ArrayList<Long>a=new ArrayList<>();while(c.moveToNext())a.add(c.getLong(0));c.close();for(long id:a)updateFee(id,newFee,false,date);return a.size();}
 public int[] scheduleDaysAt(String g,String date){Cursor c=getReadableDatabase().rawQuery("SELECT weekday FROM group_schedule WHERE groupName=? AND effectiveFrom<=? AND (effectiveTo IS NULL OR effectiveTo>=?) ORDER BY weekday",new String[]{g,date,date});ArrayList<Integer>a=new ArrayList<>();while(c.moveToNext())a.add(c.getInt(0));c.close();int[]x=new int[a.size()];for(int i=0;i<a.size();i++)x[i]=a.get(i);return x;}public void setSchedule(String g,boolean[] selected,String from){SQLiteDatabase d=getWritableDatabase();String prev=dayBefore(from);d.execSQL("DELETE FROM group_schedule WHERE groupName=? AND effectiveFrom>=?",new Object[]{g,from});d.execSQL("UPDATE group_schedule SET effectiveTo=? WHERE groupName=? AND effectiveFrom<? AND (effectiveTo IS NULL OR effectiveTo>=?)",new Object[]{prev,g,from,from});for(int i=0;i<selected.length;i++)if(selected[i]){ContentValues v=new ContentValues();v.put("groupName",g);v.put("weekday",i+2>7?1:i+2);v.put("effectiveFrom",from);d.insert("group_schedule",null,v);}}
 public ArrayList<String> trainingDates(String g,int y,int m){ArrayList<String>o=new ArrayList<>();Calendar c=Calendar.getInstance();c.clear();c.set(y,m-1,1);for(int day=1;day<=c.getActualMaximum(Calendar.DAY_OF_MONTH);day++){c.set(Calendar.DAY_OF_MONTH,day);String dt=iso.format(c.getTime());int wd=c.get(Calendar.DAY_OF_WEEK);for(int x:scheduleDaysAt(g,dt))if(x==wd){o.add(dt);break;}}return o;}
 public void saveAttendance(long id,String g,String date,boolean present){ContentValues v=new ContentValues();v.put("athleteId",id);v.put("groupName",g);v.put("trainingDate",date);v.put("present",present?1:0);getWritableDatabase().insertWithOnConflict("attendance",null,v,SQLiteDatabase.CONFLICT_REPLACE);}public boolean attendanceValue(long id,String date){Cursor c=getReadableDatabase().rawQuery("SELECT present FROM attendance WHERE athleteId=? AND trainingDate=?",new String[]{""+id,date});boolean p=c.moveToFirst()&&c.getInt(0)==1;c.close();return p;}public int attendancePercent(long id,String g,ArrayList<String>dates,String start){int eligible=0,present=0;String today=iso.format(new Date());for(String d:dates){if(d.compareTo(today)>0)continue;if(start!=null&&!start.isEmpty()&&d.compareTo(start)<0)continue;if(!memberOnDate(id,g,d))continue;eligible++;if(attendanceValue(id,d))present++;}return eligible==0?0:(int)Math.round(100.0*present/eligible);}
 public Cursor absentOver10Days(){return getReadableDatabase().rawQuery("SELECT a.*,MAX(CASE WHEN at.present=1 THEN at.trainingDate END) lastPresent,MAX(at.trainingDate) lastAttendance FROM athletes a JOIN groups g ON g.name=a.groupName AND g.isSportsSchool=1 JOIN attendance at ON at.athleteId=a.id WHERE a.active=1 GROUP BY a.id HAVING lastAttendance IS NOT NULL AND (lastPresent IS NULL OR julianday('now')-julianday(lastPresent)>=10) ORDER BY a.name",null);}
 public Cursor inventory(){return getReadableDatabase().rawQuery("SELECT * FROM inventory ORDER BY name",null);}public double inventoryProfit(String f,String t){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(qty*(sellUnit-buyUnit)),0) FROM inventory_tx WHERE type='OUT' AND txDate BETWEEN ? AND ?",new String[]{f,t});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}
 String dayBefore(String d){Date x=parse(d);if(x==null)return d;Calendar c=Calendar.getInstance();c.setTime(x);c.add(Calendar.DAY_OF_MONTH,-1);return iso.format(c.getTime());}String monthEnd(int y,int m){Calendar c=Calendar.getInstance();c.clear();c.set(y,m-1,1);c.set(Calendar.DAY_OF_MONTH,c.getActualMaximum(Calendar.DAY_OF_MONTH));return iso.format(c.getTime());}
}